OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager)
{
    OPJ_UINT32 current_data_size = 0;
    OPJ_BOOL success = OPJ_TRUE;

    while (success && current_data_size < p_total_data_size) {
        OPJ_UINT32 tile_part_size;

        /* Write the header for the current tile part */
        tile_part_size = write_tile_part_header(p_j2k, p_data + current_data_size, p_manager);

        if (tile_part_size == 0) {
            return OPJ_FALSE;
        }

        /* Write the data for the tile part */
        if (!write_tile_part_data(p_j2k, p_data + current_data_size + sizeof(OPJ_UINT16), tile_part_size - sizeof(OPJ_UINT16), p_manager)) {
            return OPJ_FALSE;
        }

        current_data_size += tile_part_size;

        /* Manage markers if needed */
        if (p_j2k->current_tile_part == 0) {
            write_marker(p_stream, MKR_SOT, p_manager);
        } else {
            write_marker(p_stream, MKR_EPH, p_manager);
        }
    }

    *p_data_written = current_data_size;
    return success;
}

OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_UINT32 written = 0;

    if (!p_j2k || !p_data || !p_data_written || !p_stream || !p_manager) {
        return OPJ_FALSE;
    }

    *p_data_written = 0;

    for (OPJ_UINT32 tile_idx = 0; tile_idx < p_j2k->num_decompress_tiles; ++tile_idx) {
        opj_tcp_t *tcp = p_j2k->tcp;
        opj_tcd_t *tcd = p_j2k->tcd;

        for (OPJ_UINT32 part_idx = 0; part_idx < tcp->num_tile_parts; ++part_idx) {
            opj_tile_part_t *tp = &tcd->tile_parts[part_idx];

            if (written + tp->data_size > p_total_data_size) {
                return OPJ_FALSE;
            }

            if (!opj_stream_write_data(p_stream, tp->data, tp->data_size, p_manager)) {
                return OPJ_FALSE;
            }

            written += tp->data_size;
        }
    }

    *p_data_written = written;
    return OPJ_TRUE;
}

OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written, OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream, struct opj_event_mgr *p_manager)
{
    OPJ_UINT32 data_written = 0;
    OPJ_UINT32 tile_idx = 0;
    OPJ_UINT32 num_tile_parts = 0;
    OPJ_UINT32 tile_part_idx = 0;

    if (!p_j2k || !p_data || !p_data_written || !p_stream || !p_manager) {
        return OPJ_FALSE;
    }

    num_tile_parts = p_j2k->number_of_tile_parts;

    for (tile_idx = 0; tile_idx < p_j2k->number_of_tiles; ++tile_idx) {
        for (tile_part_idx = 0; tile_part_idx < num_tile_parts; ++tile_part_idx) {
            OPJ_UINT32 tile_part_size = 0;
            OPJ_BYTE *tile_part_data = NULL;

            tile_part_data = p_j2k->tiles[tile_idx].data[tile_part_idx];
            tile_part_size = p_j2k->tiles[tile_idx].tile_part_size[tile_part_idx];

            if (data_written + tile_part_size > p_total_data_size) {
                return OPJ_FALSE;
            }

            /* Write tile part header */
            if (tile_part_idx == 0) {
                if (opj_write_bytes(p_stream, (OPJ_BYTE *) "\xFF\x51", 2) != 2) {
                    return OPJ_FALSE;
                }
                data_written += 2;
            }

            /* Write tile part data */
            if (opj_write_bytes(p_stream, tile_part_data, tile_part_size) != tile_part_size) {
                return OPJ_FALSE;
            }

            data_written += tile_part_size;
        }
    }

    *p_data_written = data_written;
    return OPJ_TRUE;
}

OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written,
                                   OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream,
                                   struct opj_event_mgr *p_manager) {
    OPJ_UINT32 data_written = 0;
    OPJ_BOOL success = OPJ_TRUE;

    for (OPJ_UINT32 tile_index = 0; tile_index < p_j2k->cinfo->numresolution; ++tile_index) {
        opj_j2k_tile_t *tile = &p_j2k->tiles[tile_index];

        for (OPJ_UINT32 part_index = 0; part_index < tile->num_parts; ++part_index) {
            opj_j2k_tile_part_t *tile_part = &tile->tile_parts[part_index];
            OPJ_UINT32 part_size = tile_part->data_size;

            if (data_written + part_size > p_total_data_size) {
                opj_event_msg(p_manager, EVT_ERROR, "Not enough space to write tile part.\n");
                return OPJ_FALSE;
            }

            OPJ_UINT32 bytes_written = 0;
            if (!opj_stream_write(p_stream, p_data + data_written, part_size)) {
                opj_event_msg(p_manager, EVT_ERROR, "Failed to write tile part data.\n");
                return OPJ_FALSE;
            }

            data_written += part_size;
        }
    }

    *p_data_written = data_written;
    return success;
}

OPJ_BOOL write_jpeg2000_tile_parts(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 *p_data_written, OPJ_UINT32 p_total_data_size, opj_stream_private_t *p_stream, struct opj_event_mgr *p_manager) {
    OPJ_UINT32 bytes_written = 0;
    OPJ_BOOL success = OPJ_TRUE;
    OPJ_UINT32 tile_part_index = 0;
    OPJ_UINT32 num_tile_parts = p_j2k->number_of_tile_parts;

    while (tile_part_index < num_tile_parts && bytes_written < p_total_data_size) {
        OPJ_UINT32 tile_part_size = p_j2k->tile_parts[tile_part_index].size;
        OPJ_BYTE *tile_part_data = p_j2k->tile_parts[tile_part_index].data;

        if (bytes_written + tile_part_size > p_total_data_size) {
            success = OPJ_FALSE;
            break;
        }

        memcpy(p_data + bytes_written, tile_part_data, tile_part_size);
        bytes_written += tile_part_size;

        if (!opj_stream_write(p_stream, p_data + bytes_written - tile_part_size, tile_part_size)) {
            success = OPJ_FALSE;
            break;
        }

        tile_part_index++;
    }

    *p_data_written = bytes_written;
    return success;
}
